def build_datasets():
    print(f"正在构建权威中医药数据集...")
    
    # 构建 herbs_dataset.json
    herbs_dataset = []
    for h in HERBS_RAW:
        item = {
            "herb_name": h[0],
            "pinyin": h[1],
            "aliases": h[2],
            "category": h[3],
            "nature": h[4],
            "flavor": h[5],
            "meridians": h[6],
            "toxicity_level": h[7],
            "max_dosage": h[8],
            "dosage_range": h[9],
            "efficacy": h[10],
            "contraindications": h[11],
            "decoction_method": h[12]
        }
        herbs_dataset.append(item)
    
    herbs_path = os.path.join(DATA_DIR, "herbs_dataset.json")
    with open(herbs_path, "w", encoding="utf-8") as f:
        json.dump(herbs_dataset, f, ensure_ascii=False, indent=2)
    print(f"✅ [1/2] 成功输出临床常用中药数据集: {len(herbs_dataset)} 味 -> {herbs_path}")

    # 构建 formulas_dataset.json
    formulas_dataset = []
    for f in FORMULAS_RAW:
        comp = []
        for c in f[4]:
            comp.append({
                "name": c[0],
                "dose": c[1],
                "unit": "g",
                "role": c[2]
            })
        item = {
            "formula_name": f[0],
            "source_book": f[1],
            "author": f[2],
            "category": f[3],
            "composition": comp,
            "indications": f[5],
            "monarch_herb": f[6],
            "minister_herb": f[7],
            "assistant_herb": f[8],
            "guide_herb": f[9]
        }
        formulas_dataset.append(item)

    formulas_path = os.path.join(DATA_DIR, "formulas_dataset.json")
    with open(formulas_path, "w", encoding="utf-8") as f:
        json.dump(formulas_dataset, f, ensure_ascii=False, indent=2)
    print(f"✅ [2/2] 成功输出古代经典名方数据集: {len(formulas_dataset)} 首 -> {formulas_path}")

if __name__ == "__main__":
    build_datasets()
